const client = msg.metadata.source;


msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + client.client_specific.log_id + "/entries";

msg.headers = { "Authorization": "Bearer " + client.client_specific.api_key };


return msg;

const connectionName = msg.metadata?.connection_name || null;
const sourceIdentifier = msg.metadata?.source?.identifier || null;

if (connectionName && sourceIdentifier) {
    const failureCounts = global.get("failure_counts") || {};
    delete failureCounts[`${connectionName}::${sourceIdentifier}`];
    global.set("failure_counts", failureCounts);
}
